(25526, 'John 6:4', 'John', 6, 4, 'د یهودیانو د فسحې د اختر ورځې نژدې وې.', 'د یهودیانو د فسحې د اختر ورجې نژدې وې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25527, 'John 6:5', 'John', 6, 5, 'کله چې عیسی شاوخوا ته وکتل او ګڼ شمېر خلک یې ولیدل چې د هغه خواته راروان دي، نو فیلیپوس ته یې وویل: «دومره ډوډۍ به له کوم ځای نه اخلو چې دا ټول خلک یې وخوري؟»', 'کله چې عیسی شاوخوا ته وکتل او ګن شمېر خلک یې ولیدل چې د هغه خواته راروان دی، نو فیلیپوس ته یې وویل: «دومره دودی به له کوم جای نه اخلو چې دا تول خلک یې وخوری؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25528, 'John 6:6', 'John', 6, 6, 'عیسی دا خبره د دې دپاره وکړه چې فیلیپوس امتحان کړي، ځکه چې هغه خپله پوهېده چې څه وکړي.', 'عیسی دا خبره د دې دپاره وکره چې فیلیپوس امتحان کری، جکه چې هغه خپله پوهېده چې چه وکری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25529, 'John 6:7', 'John', 6, 7, 'فیلیپوس ځواب ورکړ: «د سپینو زرو د دوه سوه سکو ډوډۍ به هم بس نه شي چې هر یو ته لږه لږه هم ورسیږي.»', 'فیلیپوس جواب ورکر: «د سپینو زرو د دوه سوه سکو دودی به هم بس نه شی چې هر یو ته لزه لزه هم ورسیزی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25530, 'John 6:8', 'John', 6, 8, 'د هغه په شاګردانو کې یو شاګرد چې اندریاس نومېده او د شمعون پطروس ورور ؤ، هغه ته وویل:', 'د هغه په شاګردانو کې یو شاګرد چې اندریاس نومېده او د شمعون پطروس ورور و، هغه ته وویل:', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25531, 'John 6:9', 'John', 6, 9, '«دلته یو هلک دی. د هغه سره د اوربشو پنځه ډوډۍ او دوه ماهیان شته، خو په هغو باندې به د دې دومره خلکو څه وشي؟»', '«دلته یو هلک دی. د هغه سره د اوربشو پنجه دودی او دوه ماهیان شته، خو په هغو باندې به د دې دومره خلکو چه وشی؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25532, 'John 6:10', 'John', 6, 10, 'عیسی هغوی ته وویل: «خلکو ته ووایئ چې کښېني.» په هغه ځای کې ډېر واښه وو، نو ټول سړي چې شمېر یې پنځه زره وو کښېناستل.', 'عیسی هغوی ته وویل: «خلکو ته ووایی چې کشېنی.» په هغه جای کې دېر واشه وو، نو تول سری چې شمېر یې پنجه زره وو کشېناستل.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25533, 'John 6:11', 'John', 6, 11, 'بیا عیسی ډوډۍ راواخیستلې، د خدای شکر یې وویست او هغه یې په ناستو خلکو باندې ووېشلې. د ماهیانو سره یې هم همداسې وکړل او چا چې څومره غوښتل ورته یې ورکړل.', 'بیا عیسی دودی راواخیستلې، د خدای شکر یې وویست او هغه یې په ناستو خلکو باندې ووېشلې. د ماهیانو سره یې هم همداسې وکرل او چا چې چومره غوشتل ورته یې ورکرل.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237833, 1761237833),
(25534, 'John 6:12', 'John', 6, 12, 'کله چې ټول ماړه شول نو خپلو شاګردانو ته یې وویل: «د پاتې شویو ډوډیو ټوټې راټولې کړئ چې هېڅ شی درڅخه ضایع نه شي.»', 'کله چې تول ماره شول نو خپلو شاګردانو ته یې وویل: «د پاتې شویو دودیو توتې راتولې کری چې هېچ شی درچخه ضایع نه شی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25535, 'John 6:13', 'John', 6, 13, 'نو شاګردانو هغه راټولې کړې او د اوربشو د پنځو ډوډیو د پاتې شویو ټوټو نه چې خلکو خوړلې وې دولس ټوکرۍ ډکې شوې.', 'نو شاګردانو هغه راتولې کرې او د اوربشو د پنجو دودیو د پاتې شویو توتو نه چې خلکو خورلې وې دولس توکری دکې شوې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25536, 'John 6:14', 'John', 6, 14, 'کله چې خلکو د عیسی معجزه ولیدله نو ویې ویل: «دا په رښتیا هماغه پیغمبر دی چې باید نړۍ ته راغلی وای.»', 'کله چې خلکو د عیسی معجزه ولیدله نو ویې ویل: «دا په رشتیا هماغه پیغمبر دی چې باید نری ته راغلی وای.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25537, 'John 6:15', 'John', 6, 15, 'بیا عیسی پوه شو چې هغوی نیت لري چې راشي او هغه په زوره بوځي او پاچا یې کړي. نو هغه بېرته د غونډیو سیمې ته لاړ چې هلته یوازې واوسیږي. عیسی د اوبو دپاسه ګرځي (متي ۱۴‏:‌۲۲‌‏-‌۳۳ او مرقوس ۶‏:‌۴۵‌‏-‌۵۲)', 'بیا عیسی پوه شو چې هغوی نیت لری چې راشی او هغه په زوره بوجی او پاچا یې کری. نو هغه بېرته د غوندیو سیمې ته لار چې هلته یوازې واوسیزی. عیسی د اوبو دپاسه ګرجی (متی ۱۴‏:‌۲۲‌‏-‌۳۳ او مرقوس ۶‏:‌۴۵‌‏-‌۵۲)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25538, 'John 6:16', 'John', 6, 16, 'کله چې ماښام شو نو د عیسی شاګردان ښکته د بحیرې خواته لاړل،', 'کله چې ماشام شو نو د عیسی شاګردان شکته د بحیرې خواته لارل،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
(25539, 'John 6:17', 'John', 6, 17, 'کشتۍ ته وختل او بېرته د بحیرې بلې غاړې ته د کپرناحوم خواته روان شول. شپه شوه او عیسی لا بېرته هغوی ته نه ؤ راغلی.', 'کشتی ته وختل او بېرته د بحیرې بلې غارې ته د کپرناحوم خواته روان شول. شپه شوه او عیسی لا بېرته هغوی ته نه و راغلی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_6_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237833, 1761237833),
